        transactNo, 
        actionType, 
        actionDate, 
        performedBy, 
        oldValues, 
        newValues
    ) 
    VALUES (
        OLD.bookingId, 
        OLD.transactNo, 
        'UPDATE', 
        CURRENT_TIMESTAMP, 
        @current_user_id,
        CONCAT('BookingId: ', OLD.bookingId, ', TransactNo: ', OLD.transactNo, ', Status: ', OLD.status), 
        CONCAT('BookingId: ', NEW.bookingId, ', TransactNo: ', NEW.transactNo, ', Status: ', NEW.status)
    );
END
$$
