DELIMITER $$
CREATE TRIGGER `after_payment_insert` AFTER INSERT ON `payment` FOR EACH ROW BEGIN
    -- Ensure @current_user_id is set if it's NULL
    IF @current_user_id IS NULL THEN
        SET @current_user_id = 'SYSTEM';
    END IF;

        paymentId, transactNo, actionType, actionDate, performedBy, oldValues, newValues
    )
    VALUES (
        NEW.paymentId,
        NEW.transactNo,
        'INSERT',
        CURRENT_TIMESTAMP,
        @current_user_id,
        NULL,
        CONCAT(
            'New Payment Details - Transact No: ', NEW.transactNo, 
            ', Title: ', NEW.paymentTitle, 
            ', Type: ', NEW.paymentType, 
            ', Amount: ₱', FORMAT(NEW.amount, 2), 
            ', Status: ', NEW.paymentStatus
        )
    );
END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `after_payment_update` AFTER UPDATE ON `payment` FOR EACH ROW BEGIN
    DECLARE currentStatus VARCHAR(50);
    DECLARE paymentCount INT;
    DECLARE bookingId INT;

    -- Ensure @current_user_id is set if it's NULL
    IF @current_user_id IS NULL THEN
        SET @current_user_id = 'SYSTEM';
    END IF;

    -- Fetch the current booking status
    SELECT b.bookingId, b.status
    INTO bookingId, currentStatus
    FROM booking b
    WHERE b.transactNo = NEW.transactNo
    LIMIT 1;

    -- Count the number of approved payments for this transaction
    SELECT COUNT(*) INTO paymentCount
    FROM payment
    WHERE transactNo = NEW.transactNo AND paymentStatus = 'Approved';

    -- If this is the first approved payment, and booking not yet confirmed, update status
    IF paymentCount = 1 AND currentStatus != 'Confirmed' THEN
        UPDATE booking
        SET status = 'Confirmed'
        WHERE transactNo = NEW.transactNo;
    END IF;

    -- Insert audit entry
        paymentId, 
        transactNo, 
        actionType, 
        actionDate, 
        performedBy, 
        oldValues, 
        newValues
    )
    VALUES (
        OLD.paymentId,
        OLD.transactNo,
        'UPDATE',
        CURRENT_TIMESTAMP,
        @current_user_id,
        CONCAT(
            'Old Payment - Transact No: ', OLD.transactNo, ', Title: ', OLD.paymentTitle, 
            ', Type: ', OLD.paymentType, ', Amount: ₱', FORMAT(OLD.amount, 2), ', Status: ', OLD.paymentStatus
        ),
        CONCAT(
            'New Payment - Transact No: ', NEW.transactNo, ', Title: ', NEW.paymentTitle, 
            ', Type: ', NEW.paymentType, ', Amount: ₱', FORMAT(NEW.amount, 2), ', Status: ', NEW.paymentStatus
        )
    );
END
$$
DELIMITER ;

